import{c as t,Q as a,j as r,m as o}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"GetPowerTmpBufferFactorSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetPowerTmpBufferFactorSize","slug":"getpowertmpbufferfactorsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/数学计算/Power接口/GetPowerTmpBufferFactorSize.md","filePath":"api/SIMD-API/高阶API/数学计算/Power接口/GetPowerTmpBufferFactorSize.md"}'),i={name:"api/SIMD-API/高阶API/数学计算/Power接口/GetPowerTmpBufferFactorSize.md"};function s(n,e,d,l,p,u){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="getpowertmpbufferfactorsize" tabindex="-1">GetPowerTmpBufferFactorSize <a class="header-anchor" href="#getpowertmpbufferfactorsize" aria-label="Permalink to &quot;GetPowerTmpBufferFactorSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>该接口用于获取maxLiveNodeCount和extraBuf，在固定空间大小的情况下，通过maxLiveNodeCount和extraBuf可以推算算子单次最大计算元素数量。maxLiveNodeCount表示临时空间是单次计算数据量所占空间的多少倍；extraBuf表示使用的额外临时空间大小。</p><p>推算示例如下：</p><p>算子实现需要调用Power接口，开发者为其预留currBuff大小的空间，利用GetPowerTmpBufferFactorSize接口得到maxLiveNodeCount、extraBuf输出值，可推导算子单次最大计算元素数量为：</p><p><strong>currentShapeSize = (currBuff - extraBuf) / maxLiveNodeCount / typeSize</strong></p><p>注意上文中的currBuff表示接口计算可用的空间，需要去除用户输入输出等空间；另外，接口获取的maxLiveNodeCount值可能为0，计算时需要判断该值非0，避免除零错误。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetPowerTmpBufferFactorSize(const bool baseIsTensor, const bool expIsTensor, const bool typeIsInt, const uint32_t typeSize, uint32_t&amp; maxLiveNodeCount, uint32_t&amp; extraBuffer)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数列表</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>baseIsTensor</td><td>输入</td><td>底数是Tensor输入true，否则输入false</td></tr><tr><td>expIsTensor</td><td>输入</td><td>指数是Tensor输入true，否则输入false</td></tr><tr><td>typeIsInt</td><td>输入</td><td>数据类型是int时输入true，否则输入false</td></tr><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处应传入2。</td></tr><tr><td>maxLiveNodeCount</td><td>输出</td><td>最大存活节点数，表示临时空间是单次计算数据量所占空间的多少倍。</td></tr><tr><td>extraBuffer</td><td>输出</td><td>使用的额外临时空间大小，单位为字节。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>当利用maxLiveNodeCount，extraBuf反推出的currentShapeSize * typeSize &lt; 256B时，currentShapeSize按照256B/typeSize的值向上取整。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的调用样例请参考<a href="./../更多样例-83.html">更多样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t maxLiveNodeCount = 0;</span></span>
<span class="line"><span>uint32_t extraBuf = 0;</span></span>
<span class="line"><span>AscendC::GetPowerTmpBufferFactorSize(true, true, true, 4, maxLiveNodeCount, extraBuf);</span></span></code></pre></div>`,19)])])}const h=t(i,[["render",s]]);export{f as __pageData,h as default};
